[InitializeOnLoad]public static class HospitalRoadsideUpgrade{static HospitalRoadsideUpgrade(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("HospitalRoadsideUpgrade.request"))return;File.Delete("HospitalRoadsideUpgrade.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/HospitalRoadsideUpgrade.txt",e.ToString());Debug.LogException(e);}}static void Run(){const string d="Assets/Scenes/Oasis/CityHospital/";var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(scene.GetRootGameObjects().Any(g=>g.name=="Hospital billboard 8 low poly branding"))throw new Exception("Hospital billboard already installed");var f=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Single(g=>g.name=="billboard (8)");var nativeMesh=f.sharedMesh;var nativeMatrix=f.transform.localToWorldMatrix;Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeHospitalRoadsideSign");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeHospitalRoadsideSign/Scene.unity",true);var mat=AssetDatabase.LoadAssetAtPath<Material>(d+"City Hospital Mobile.mat");var root=new GameObject("Hospital billboard 8 low poly branding");root.transform.position=new Vector3(-93.156f,36.89f,-299.934f);var renderers=new Renderer[2];var counts=new int[2];for(int l=0;l<2;l++){var mesh=StackHouse3DSigns.BuildHospitalRoadside(mat,l==0);counts[l]=mesh.triangles.Length/3;AssetDatabase.CreateAsset(mesh,d+"Hospital billboard 8 "+(l==0?"near":"far")+".asset");var go=new GameObject(l==0?"Raised red medical cross and hospital atlas lettering":"Distant hospital atlas logo");go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;renderers[l]=r;}var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.07f,new[]{renderers[0]}),new LOD(.003f,new[]{renderers[1]})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAssetAndConnect(root,d+"Hospital billboard 8 low poly branding.prefab",InteractionMode.AutomatedAction);if(f.sharedMesh!=nativeMesh||f.transform.localToWorldMatrix!=nativeMatrix)throw new Exception("Original pole platform or billboard changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(-82,39,-282),new Vector3(-93,34,-300),"Hospital-Billboard-8-Front"});capture.Invoke(null,new object[]{scene,new Vector3(-105,39,-317),new Vector3(-93,34,-300),"Hospital-Billboard-8-Back"});File.WriteAllText("FinalEnvironmentRoadReview/HospitalRoadsideUpgrade.txt","SUCCESS billboard (8) front/back hospital branding. Existing hospital atlas/material reused, zero new runtime texture/material or lights. Low poly raised red medical cross plus blue-white CITY HOSPITAL atlas lettering and heartbeat. Native billboard pole/platform/frame and transforms unchanged. Near triangles="+counts[0]+", far="+counts[1]+". LOD and prefab saved. Shader errors="+ShaderUtil.ShaderHasError(mat.shader));}}
